  const now = new Date().toISOString()
  const id = generateTimestampId()
  const obligation: Obligation = {
    id,
    origin: input.origin,
    ...(input.bridgeId ? { bridgeId: input.bridgeId } : {}),
    content: input.content,
    status: "pending",
    createdAt: now,
    updatedAt: now,
  }

  writeJsonFile(obligationsDir(agentRoot), id, obligation)

  emitNervesEvent({
    component: "engine",
